15	func main() {
16		command := "demo"
17		if len(os.Args) > 1 {
18			command = os.Args[1]
19		}
20		switch command {
21		case "demo":
22			runDemo()
23		case "version":
24			fmt.Println("mevwatch 0.1.0")
25		case "replay":
26			runReplay(os.Args[2:])
27		case "report":
28			if len(os.Args) != 5 {
29				fmt.Fprintln(os.Stderr, "usage: mevwatch report <archive-dir> <chainId> <blockHash>")
30				os.Exit(2)
31			}
32			report, err := mevwatch.Query(os.Args[2], os.Args[3], os.Args[4])
33			if err != nil {
34				fmt.Fprintf(os.Stderr, "report: %v\n", err)
35				os.Exit(1)
36			}
37			writeJSON(report)
38		case "rules":
39			runRules(os.Args[2:])
40		case "alerts":
41			runAlerts(os.Args[2:])
42		case "suppressions":
43			runSuppressions(os.Args[2:])
44		case "reviews":
45			runReviews(os.Args[2:])
46		case "compare":
47			if len(os.Args) != 6 {
48				fmt.Fprintln(os.Stderr, "usage: mevwatch compare <archive-dir> <chainId> <blockHash> <version-id>")
49				os.Exit(2)
50			}
51			result, err := mevwatch.Compare(os.Args[2], os.Args[3], os.Args[4], os.Args[5])
52			if err != nil {
53				fmt.Fprintf(os.Stderr, "compare: %v\n", err)
54				os.Exit(1)
55			}
56			writeJSON(result)
57		case "help", "-h", "--help":
58			usage()
59		default:
60			fmt.Fprintf(os.Stderr, "unknown command %q\n", command)
61			usage()
62			os.Exit(2)
63		}
64	}
