66	func usage() {
67		fmt.Println("usage: mevwatch [command]")
68		fmt.Println("  demo                                     run the built-in sandwich demo (default)")
69		fmt.Println("  version                                  print version")
70		fmt.Println("  replay [--version <id>] <input> <dir>    import line-delimited blocks into the archive")
71		fmt.Println("  report <archive-dir> <chainId> <hash>    print the archived block report")
72		fmt.Println("  rules list <archive-dir>                 list rule versions and the enabled one")
73		fmt.Println("  rules show <archive-dir> <version-id>    print one version's full parameters")
74		fmt.Println("  rules register <archive-dir> <spec-file> register a rule version ('-' reads stdin)")
75		fmt.Println("  rules enable <archive-dir> <version-id>  enable a registered version for later replays")
76		fmt.Println("  compare <archive-dir> <chainId> <hash> <version-id>")
77		fmt.Println("                                           re-judge an archived block under a version and diff")
78		fmt.Println("  alerts generate <archive-dir> <chainId> <startHeight> <endHeight> <minSeverity> <channel>")
79		fmt.Println("                                           generate offline alerts from archived conclusions")
80		fmt.Println("  alerts history <archive-dir> <chainId> <channel> <startHeight> <endHeight>")
81		fmt.Println("                                           query stored alert/suppression records")
82		fmt.Println("  suppressions list <archive-dir>          list registered suppression conditions")
83		fmt.Println("  suppressions register <archive-dir> <spec-file>")
84		fmt.Println("                                           register a suppression condition ('-' reads stdin)")
85		fmt.Println("  suppressions revoke <archive-dir> <id>   revoke a registered suppression condition")
86		fmt.Println("  reviews submit <archive-dir> <spec-file> submit a manual review ('-' reads stdin)")
87		fmt.Println("  reviews history <archive-dir> <chainId> <blockHash> <txHash> <kind>")
88		fmt.Println("                                           query a conclusion's current review and revisions")
89		fmt.Println("  reviews evaluate <archive-dir> <chainId> <startHeight> <endHeight> <version-id>")
90		fmt.Println("                                           false-positive analysis over a height range")
91	}
