1192	func TestRevokeSuppressionConcurrentConsistent(t *testing.T) {
1193		dir := t.TempDir()
1194		mustReplay(t, dir, twoFindingsInput)
1195		spec := `{"id":"s1","chainId":"1","pool":"p1","kind":"sandwich","channel":"ops","startHeight":0,"endHeight":200,"reason":"r"}`
1196		if _, _, err := RegisterSuppression(dir, []byte(spec)); err != nil {
1197			t.Fatal(err)
1198		}
1199	
1200		const n = 12
1201		var wg sync.WaitGroup
1202		genErrs := make([]error, n)
1203		statuses := make([]string, n)
1204		start := make(chan struct{})
1205		// Half the goroutines generate, half revoke, all retrying through busy
1206		// errors the way a real caller does. Each generation must observe one
1207		// consistent condition set (suppressed pre-revoke or alert post-revoke),
1208		// never a half state.
1209		retryBusy := func(op func() error) error {
1210			for attempt := 0; attempt < 1000; attempt++ {
1211				err := op()
1212				if errors.Is(err, ErrBusy) {
1213					time.Sleep(time.Millisecond)
1214					continue
1215				}
1216				return err
1217			}
1218			return ErrBusy
1219		}
1220		for i := 0; i < n; i++ {
1221			wg.Add(1)
1222			go func(i int) {
1223				defer wg.Done()
1224				<-start
1225				if i%2 == 0 {
1226					genErrs[i] = retryBusy(func() error {
1227						recs, err := GenerateAlerts(dir, "1", "ops", 0, 100, 1)
1228						if err == nil {
1229							for _, r := range recs {
1230								if r.Finding.TxHash == "0xv" {
1231									statuses[i] = r.Status
1232								}
1233							}
1234						}
1235						return err
1236					})
1237				} else {
1238					genErrs[i] = retryBusy(func() error {
1239						_, _, err := RevokeSuppression(dir, "s1")
1240						return err
1241					})
1242				}
1243			}(i)
1244		}
1245		close(start)
1246		wg.Wait()
1247	
1248		for i, err := range genErrs {
1249			if err != nil {
1250				t.Fatalf("goroutine %d unexpected error: %v", i, err)
1251			}
1252		}
1253		// Exactly one generation creates the sandwich record; its status must be
1254		// one coherent outcome, and only the matching condition ids are stored.
1255		hist, err := AlertHistory(dir, "1", "ops", 0, 100)
1256		if err != nil {
1257			t.Fatal(err)
1258		}
1259		final := ""
1260		count := 0
1261		for _, r := range hist {
1262			if r.Finding.TxHash == "0xv" {
1263				count++
1264				final = r.Status
1265				if len(r.Suppressions) > 1 {
1266					t.Fatalf("inconsistent hit set: %+v", r.Suppressions)
1267				}
1268			}
1269		}
1270		if count != 1 {
1271			t.Fatalf("sandwich processed %d times, want exactly 1", count)
1272		}
1273		if final != AlertStatusAlert && final != AlertStatusSuppressed {
1274			t.Fatalf("final status %q is neither coherent pre/post-revocation state", final)
1275		}
1276		// The generator that created the record reports the same status it
1277		// committed; no generator may return an incoherent status.
1278		nonEmpty := 0
1279		for i, s := range statuses {
1280			if s == "" {
1281				continue
1282			}
1283			nonEmpty++
1284			if s != final {
1285				t.Fatalf("generator %d observed status %q but history holds %q", i, s, final)
1286			}
1287		}
1288		if nonEmpty != 1 {
1289			t.Fatalf("exactly one generation must create the record, %d reported it", nonEmpty)
1290		}
1291	}
